from pathlib import Path
base=Path('docs/qa/harness/728-firstload/controller-surface6b.mjs').read_text()
prefix=base.split('try{\n const ram=')[0]
prefix=prefix.replace("import {original47,materialGuard,mapped47} from './guards.mjs';", "import {original47,materialGuard,mapped47} from './guards.mjs';\nimport {durable47} from './socket-seed.mjs';\nimport {isDeepStrictEqual} from 'node:util';")
prefix=prefix.replace("if(process.env.QA_DRY_RUN==='1'){", "const seedRecord=JSON.parse(fs.readFileSync(process.env.QA_SEED_RECORD,'utf8'));durable47(seedRecord.actual,seedRecord.mapped);mapped47(seedRecord.mapped,seedRecord.author,seedRecord.namespace);\nif(process.env.QA_DRY_RUN==='1'){")
prefix=prefix.replace("const endpoints=new Map();", "const endpoints=new Map();\nconst privatePath=process.env.QA_PRIVATE_AUTH;if(!privatePath||(fs.statSync(privatePath).mode&0o077)!==0)throw Error('Private identity file0600 required');\nconst cookies=JSON.parse(fs.readFileSync(privatePath,'utf8')).cookies;if(!Array.isArray(cookies)||!cookies.length)throw Error('Normal identity cookies required');\nconst contexts=new Set();let activeContext;")
# Dry run returns before private file reads; report does not contain cookies.
main=r'''
const roomURL=APP+'/room/'+encodeURIComponent(seedRecord.roomId);
async function openReader(elide,count,label){
 if(page){await page.close();page=null}if(activeContext){await activeContext.close();contexts.delete(activeContext)}
 activeContext=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:640,height:480}});contexts.add(activeContext);
 await activeContext.addCookies(cookies.map(({name,value,httpOnly,sameSite})=>({name,value,url:APP,httpOnly,sameSite,secure:new URL(APP).protocol==='https:'})));
 await activeContext.addInitScript({path:process.env.QA_PROBE??new URL('./room-probe.js',import.meta.url).pathname});
 page=await activeContext.newPage();page.on('dialog',d=>void d.accept());page.on('pageerror',e=>{report.errors.push(String(e));save()});
 const arm={label,elide,count,stage:'ordinary-navigation',joinStart:Date.now()};report.arms.push(arm);save();
 await page.goto(roomURL+'?qaClearPrefixElision='+Number(elide));await ready(page,label);await waitIdle(page,count);arm.joinWall=Date.now()-arm.joinStart;
 const identity=await page.evaluate(()=>({actor:__roomStore.getState().userId,engineActor:__engine._userId,room:__roomStore.getState().room,page:__engine._pageSize(),paperLoaded:__engine._paper.loaded}));
 if(identity.actor!==seedRecord.author||identity.engineActor!==seedRecord.author)throw Error('Normal own identity differs');
 if(identity.room.width!==1754||identity.room.height!==2480||identity.room.paper!=='fine'||identity.room.paperColor?.toLowerCase()!=='#fdfdfc'||identity.page.w!==1754||identity.page.h!==2480||!identity.paperLoaded)throw Error('Original Fine1754x2480 passport');arm.identity=identity;
 arm.loadedSource=await page.evaluate(async()=>{const out=[];for(const path of ['/src/pages/Room/index.tsx','/src/pages/Room/useRoomRestore.ts','/src/pages/Room/restoreRoomState.ts','/src/pages/Room/clearedInBatch.ts','/src/pages/Room/diagnostics/clearPrefixElision.ts','/src/engine/index.ts']){const text=(await import(path+'?raw')).default;const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(b=>b.toString(16).padStart(2,'0')).join('');out.push({path,hash})}return out});
 for(const q of arm.loadedSource){const expected=passport.files.find(f=>f.path==='apps/web'+q.path);if(expected?.sha256!==q.hash)throw Error('Actual source SHA '+q.path)}
 arm.paperSHA=await page.evaluate(async()=>{const out=[];for(const path of ['/paper/fine.e59ea6fa.paper','/paper/manifest.json']){const r=await fetch(path);if(!r.ok)throw Error('Paper HTTP '+r.status);const bytes=await r.arrayBuffer();out.push({path,bytes:bytes.byteLength,sha:[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('')})}return out});
 if(arm.paperSHA[0].sha!=='4c631b8c5da1813977aeb34405fa223ebf74b59a0b5df951e23d71f986a26968'||arm.paperSHA[1].sha!=='385e31d3e26901d63f81e9d6c56b6f7af26b2f33eb3dc4db16725b6e378884ac')throw Error('Actual paper SHA');
 const result=await capture(page,label);arm.capture=result.result;arm.paintCalls=result.result.trace.calls.filter(q=>q.name==='_paintDabs').length;arm.stage='quiet-captured';save();return{arm,...result};
}
async function durable(count,expected){
 const deadline=Date.now()+15000;while(Date.now()<deadline){const actual=await page.evaluate(async()=>{const id=__roomStore.getState().room.id;const r=await fetch('/api/rooms/'+id+'/operations?beforeSeq=1000000000&limit=500');if(!r.ok)throw Error('Durable REST '+r.status);return r.json()});if(actual.length===count){if(new Set(actual.map(o=>o.id)).size!==count||actual.some((o,i)=>o.seq!==i+1||o.userId!==seedRecord.author))throw Error('Durable ID/seq/author');for(let i=0;i<count;i++){const value={...actual[i]};delete value.seq;if(!isDeepStrictEqual(value,expected[i]))throw Error('Durable physical prefix/type/target differs '+i)}return actual}await new Promise(r=>setTimeout(r,200))}throw Error('Durable history deadline');
}
try{
 const ram=memoryAvailable();report.memoryDevice='Surface actual remote RAM';report.memAvailable=ram;if(!remoteCDP||ram<1700)throw Error('Surface CDP / RAM1700 required');save();
 browser=ownedRemoteBrowser(await chromium.connectOverCDP(remoteCDP,{timeout:30000}));
 report.scope='One existing normal Socket seeded room; ordinary OFF47/ON47 before history/snapshot; independent OFF48 semantic oracle; real49 uploader/stored49. No local GL seed or seedPNG.';
 const off=await openReader(false,47,'ordinary-off47');await durable(47,seedRecord.mapped);
 const status=await page.evaluate(async()=>{const r=await fetch('/api/rooms/'+__roomStore.getState().room.id+'/snapshots/index');return r.status});if(status!==204)throw Error('Actual no snapshot before ordinary47');off.arm.snapshotStatus=status;
 if(off.arm.paintCalls!==39||off.result.trace.dropped)throw Error('OFF39 physical paint census');
 const on=await openReader(true,47,'ordinary-on47');await durable(47,seedRecord.mapped);on.arm.offVsOn=compare(off.png,on.png);if(on.arm.offVsOn.changed)throw Error('Ordinary47 OFF/ON RGBA');
 if(on.arm.paintCalls!==31||on.result.trace.dropped||!on.result.trace.calls.some(q=>q.name==='setUnpaintedInBatch'&&q.unpaintedIds?.length===10))throw Error('ON31 / actual10skip census: inspect eligibility; no automatic retry');save();
 const clear=seedRecord.mapped.find(o=>o.type==='layer_clear');const undo={id:crypto.randomUUID(),type:'operation_undo',targetOpId:clear.id,userId:seedRecord.author,timestamp:Date.now()};
 await page.evaluate(op=>__engine.appendOperation(op),undo);await waitIdle(page,48);const history48=[...seedRecord.mapped,undo];report.durable48=await durable(48,history48);const undone=await capture(page,'on-live-undo48');report.undoDelta=compare(on.png,undone.png);if(!report.undoDelta.changed)throw Error('Undo clear pixel noop');save();
 const fresh48=await openReader(false,48,'fresh-off48');await durable(48,history48);report.undoSemantic=compare(undone.png,fresh48.png);if(report.undoSemantic.changed)throw Error('Undo vs full authoritative OFF48 replay');
 await openReader(true,48,'on-rejoin48');const redo={id:crypto.randomUUID(),type:'operation_redo',targetOpId:clear.id,userId:seedRecord.author,timestamp:Date.now()};await page.evaluate(op=>__engine.appendOperation(op),redo);await waitIdle(page,49);report.durable49=await durable(49,[...history48,redo]);const redone=await capture(page,'on-live-redo49');report.redoVsOriginal47=compare(on.png,redone.png);if(report.redoVsOriginal47.changed)throw Error('Redo vs original47');save();
 await page.evaluate(()=>__enableRealSnapshotBake());let index;const until=Date.now()+45000;while(Date.now()<until){const q=await page.evaluate(async()=>{const r=await fetch('/api/rooms/'+__roomStore.getState().room.id+'/snapshots/index');return{status:r.status,index:r.status===200?await r.json():null}});report.bootstrapPoll=q;save();if(q.index?.layers?.some(l=>l.seq===49)){index=q.index;break}if(![200,204].includes(q.status))throw Error('Snapshot index '+q.status);await new Promise(r=>setTimeout(r,250))}if(!index)throw Error('Real snapshot49 deadline');
 report.bootstrap=await page.evaluate(async index=>{const blobs=[];for(const l of index.layers){const r=await fetch('/api/rooms/'+__roomStore.getState().room.id+'/snapshots/'+encodeURIComponent(l.layerId)+'/'+l.seq);blobs.push({layerId:l.layerId,seq:l.seq,status:r.status,bytes:(await r.arrayBuffer()).byteLength})}return{index,blobs,trace:__loadTrace}},index);if(report.bootstrap.blobs.some(b=>b.status!==200||!b.bytes)||!report.bootstrap.trace.uploads.some(q=>q.status===200&&q.seq===49)||!report.bootstrap.trace.bakes.some(q=>q.bytes>0))throw Error('Actual bake49/blob proof');
 const stored=await openReader(true,49,'fresh-stored49');await durable(49,[...history48,redo]);report.storedVsRedo=compare(redone.png,stored.png);if(report.storedVsRedo.changed||stored.arm.paintCalls!==0||!stored.result.trace.calls.some(q=>q.name==='restoreLayerFromSnapshot'))throw Error('Stored49 actual bitmap/whole parity');report.complete=true;save();
}catch(error){report.error=String(error);if(page&&!page.isClosed())try{report.failureState=await Promise.race([page.evaluate(()=>({path:location.pathname,timeOrigin:performance.timeOrigin,now:performance.now(),visibility:document.visibilityState,logCount:__engine?._log.entries.length,trace:__loadTrace})),new Promise(r=>setTimeout(()=>r({diagnosticTimeout:true}),3000))])}catch(e){report.failureState={error:String(e)}}save();process.exitCode=1}finally{clearTimeout(wall);clearInterval(memory);await page?.close().catch(()=>{});for(const c of contexts)await c.close().catch(()=>{});await browser?.close();report.ownedChromeClosed=true;save()}
console.log(JSON.stringify({OUT,complete:report.complete,error:report.error,closed:report.ownedChromeClosed}));
'''
Path('docs/qa/harness/728-firstload/controller-engine-free.mjs').write_text(prefix+main)
